    void RefreshInspection()
    {
        if(_inspection==null)return;var s=_sim.State;var selected=s.Buildings.FirstOrDefault(b=>b.Id==_selectedBuilding&&!b.Removed);var project=s.Projects.FirstOrDefault(p=>p.Id==(_selectedProject??selected?.ProjectId));var key=$"{_cityId}:{_selectedBuilding}:{_selectedProject}:{_selectedCitizen}:{_selectedVehicle}:{_selectedRoad}:{s.NextId}:{s.RoadRevision}:{selected?.Completed}:{selected?.CompanyId}:{selected?.FamilyId}:{project?.Status}:"+string.Join(",",s.Citizens.Where(c=>c.Alive&&c.WorkplaceId==_selectedBuilding).Select(c=>c.Id));
        if(key==_inspectionKey){foreach(var item in _inspectionTexts)item.Label.Text=item.Read();foreach(var item in _inspectionButtons)item.Button.Text=item.Read();return;}
        _inspectionKey=key;_inspectionTexts.Clear();_inspectionButtons.Clear();Clear(_inspection);
        if(_selectedBuilding is {} id&&s.Buildings.FirstOrDefault(b=>b.Id==id&&!b.Removed) is {} b){_inspector.Visible=true;InspectionText(_inspection,()=>b.Definition.Name,22);InspectionText(_inspection,()=>b.Cause);InspectionText(_inspection,()=>"Proprietário: "+AccountName(b.OwnerAccount));InspectionText(_inspection,()=>"Água "+b.WaterRatio.ToString("P0")+" • Energia "+b.ElectricityRatio.ToString("P0"));InspectionText(_inspection,()=>"Capacidade operacional: "+b.OperationalCapacity.ToString("N1"));if(b.Definition.Private)InspectionText(_inspection,()=>"Valor de mercado: "+Cash(_sim.MarketValue(b)));else InspectionText(_inspection,()=>"Manutenção: "+b.MaintenanceRatio.ToString("P0"));if(b.Stock.Count>0)InspectionText(_inspection,()=>"Estoque: "+string.Join(" • ",b.Stock.Select(k=>ResourceName(k.Key)+" "+k.Value.ToString("N1"))));
            if(!b.Completed&&s.Projects.First(p=>p.Id==b.ProjectId) is {} p){InspectionText(_inspection,()=>"Obra "+p.Progress.ToString("P0")+" • "+p.Cause);InspectionText(_inspection,()=>"Pago "+Cash(p.CostPaid)+" • comprometido "+Cash(p.BudgetRemaining));foreach(var kv in p.Required)InspectionText(_inspection,()=>ResourceName(kv.Key)+": "+p.Delivered.GetValueOrDefault(kv.Key).ToString("N1")+" / "+kv.Value.ToString("N1")+" • reservado "+p.LocalReserved.GetValueOrDefault(kv.Key).ToString("N1"),14);ProjectControls(_inspection,p);}
            if(b.CompanyId is {} co&&s.Companies.FirstOrDefault(c=>c.Id==co) is {} company){InspectionText(_inspection,()=>company.Name,19);InspectionText(_inspection,()=>"Caixa: "+Cash(_sim.Balance(company.Account)));InspectionText(_inspection,()=>company.Decision);InspectionText(_inspection,()=>"Preço: "+Cash(b.SalePrice));}
            foreach(var c in s.Citizens.Where(c=>c.Alive&&c.WorkplaceId==b.Id)){var cid=c.Id;InspectionButton(_inspection,()=>c.Name+" • "+c.Activity,()=>InspectCitizen(cid));}if(b.FamilyId is {} fi&&s.Families.FirstOrDefault(f=>f.Id==fi) is {} family){InspectionText(_inspection,()=>"Despensa: "+family.Pantry.ToString("N1"));foreach(var cid in family.Members){var c=s.Citizens.First(c=>c.Id==cid);var copy=cid;InspectionButton(_inspection,()=>c.Name,()=>InspectCitizen(copy));}}
            InspectionButton(_inspection,()=>"⌂ Construir outro",()=>Choose(b.Kind),"Copiar tipo; a nova construção mantém custos e obra próprios");return;}
        if(_selectedProject is {} projectId&&s.Projects.FirstOrDefault(p=>p.Id==projectId) is {} selectedWork){_inspector.Visible=true;InspectionText(_inspection,()=>(selectedWork.IsMaintenance?"Manutenção #":"Obra viária #")+selectedWork.Id,22);InspectionText(_inspection,()=>selectedWork.Cause+" • "+selectedWork.Progress.ToString("P0"));InspectionText(_inspection,()=>"Pago "+Cash(selectedWork.CostPaid)+" • comprometido "+Cash(selectedWork.BudgetRemaining));foreach(var k in selectedWork.Required)InspectionText(_inspection,()=>ResourceName(k.Key)+" "+selectedWork.Delivered.GetValueOrDefault(k.Key).ToString("N1")+" / "+k.Value.ToString("N1"));ProjectControls(_inspection,selectedWork);return;}
        if(_selectedCitizen is {} ci&&s.Citizens.FirstOrDefault(c=>c.Id==ci) is {} citizen){_inspector.Visible=true;InspectionText(_inspection,()=>citizen.Name,22);InspectionText(_inspection,()=>citizen.Activity);InspectionText(_inspection,()=>citizen.Decision);InspectionText(_inspection,()=>"Carteira "+Cash(_sim.Balance(citizen.Account)));InspectionText(_inspection,()=>"Saúde "+citizen.Health.ToString("N0")+" • satisfação "+citizen.Satisfaction.ToString("N0"));InspectionText(_inspection,()=>"Sem comer há "+citizen.HungerHours.ToString("N1")+" h • alimentos transportados "+citizen.BagFood.ToString("N1"));InspectionText(_inspection,()=>"Salário acumulado: "+Cash(citizen.WagesAccrued));foreach(var h in citizen.History.TakeLast(8).Reverse())InspectionText(_inspection,()=>h.At.ToString("dd/MM HH:mm")+" "+h.Description,14);InspectionButton(_inspection,()=>"◎ Acompanhar",()=>{_focus=ToV(citizen.Position);UpdateCamera();});return;}
        if(_selectedVehicle is {} vi&&s.Vehicles.FirstOrDefault(v=>v.Id==vi) is {} vehicle){_inspector.Visible=true;InspectionText(_inspection,()=>"Caminhão "+vehicle.Id,22);InspectionText(_inspection,()=>vehicle.Cause);InspectionText(_inspection,()=>"Titular: "+AccountName(vehicle.OwnerAccount));InspectionText(_inspection,()=>"Motorista: "+(vehicle.ExternalDriverId??s.Citizens.FirstOrDefault(c=>c.Id==vehicle.DriverId)?.Name??"aguardando"));InspectionText(_inspection,()=>"Combustível: "+vehicle.Fuel.ToString("N2"));InspectionText(_inspection,()=>"Carga: "+string.Join(" • ",vehicle.Cargo.Select(k=>ResourceName(k.Key)+" "+k.Value.ToString("N1"))));InspectionText(_inspection,()=>"Equipe externa: "+vehicle.CrewCount);return;}
        if(_selectedRoad is {} ri&&s.Roads.FirstOrDefault(r=>r.Id==ri) is {} road){_inspector.Visible=true;InspectionText(_inspection,()=>road.Highway?"Rodovia externa":"Rua 1+1",22);InspectionText(_inspection,()=>"Energia dos postes: "+road.ElectricityRatio.ToString("P0"));InspectionText(_inspection,()=>"Manutenção: "+road.MaintenanceRatio.ToString("P0"));if(!road.Highway&&road.Neighbours.Count>=3)foreach(var control in Enum.GetValues<JunctionControl>()){var ctl=control;InspectionButton(_inspection,()=>ctl switch{JunctionControl.Signal=>"Semáforo",JunctionControl.ThroughX=>"Preferência horizontal",JunctionControl.ThroughZ=>"Preferência vertical",_=>"Preferência à direita"},()=>_sim.SetJunction(road.Id,ctl));}if(!road.Highway)InspectionButton(_inspection,()=>"× Remover trecho",()=>ShowRoadDemolition(road.Id));return;}
        _inspector.Visible=false;
    }
    void ProjectControls(Node parent,WorkProject project){if(project.IsMaintenance){Text(parent,"Manutenção automática; materiais e equipe municipal ou externa têm execução real.",14);return;}if(project.Status is not (WorkStatus.Waiting or WorkStatus.InProgress))return;InspectionText(parent,()=>"Cancelar libera "+Cash(Math.Max(0,project.BudgetRemaining-decimal.Round(project.CrewCostDue,2,MidpointRounding.AwayFromZero)))+"; gastos pagos/devidos ("+Cash(project.CostPaid+decimal.Round(project.CrewCostDue,2,MidpointRounding.AwayFromZero))+") e materiais entregues/consumidos não voltam.",14);Button(parent,"× Cancelar obra",()=>{_sim.CancelProject(project.Id);RefreshHud();});Button(parent,"↗ Mover obra",()=>BeginMove(project));}
    void ShowRoadDemolition(int roadId)
    {
        var quote=_sim.QuoteRoadDemolition(roadId);var box=Modal("Remover trecho de rua");Text(box,"Custo da remoção: "+Cash(quote.Cost),22);Text(box,quote.Message);Text(box,"Construções que perderão conexão exterior: "+quote.IsolatedBuildingIds.Count);foreach(var id in quote.IsolatedBuildingIds){var building=_sim.State.Buildings.First(b=>b.Id==id);Text(box,building.Definition.Name+" • "+building.Position.X.ToString("N0")+", "+building.Position.Z.ToString("N0"),14);}Text(box,"Obras com acesso interrompido: "+quote.InterruptedWorks+" • rotas atuais pelo trecho: "+quote.AffectedVehicleRoutes,14);Text(box,"Gastos originais e materiais não voltam. Pessoas e cargas permanecem nas posições reais.",14);var row=new HBoxContainer();box.AddChild(row);var confirm=Button(row,"✓ Confirmar remoção",()=>{var result=_sim.DemolishRoad(roadId);if(result.Success){ClearSelection();CloseModal();RefreshHud();}else Text(box,result.Message);});confirm.Disabled=!quote.Allowed||quote.Cost>_sim.Available;Button(row,"× Cancelar",CloseModal);
    }
    void InspectCitizen(int id){ClearSelection();ClearTool();_selectedCitizen=id;_selectedBuilding=null;_selectedVehicle=null;_selectedRoad=null;RefreshInspection();CloseModal();}
    static string ResourceName(ResourceKind r)=>r switch{ResourceKind.Aggregate=>"Areia e brita",ResourceKind.Concrete=>"Concreto",ResourceKind.Steel=>"Aço",ResourceKind.Wood=>"Madeira",ResourceKind.Asphalt=>"Asfalto",ResourceKind.Food=>"Alimentos",_=>"Combustível"};
    VBoxContainer Modal(string title)
    {
        CloseModal();var viewport=GetViewport().GetVisibleRect().Size;var width=(int)Math.Min(720,viewport.X-64);var height=(int)Math.Min(600,viewport.Y-72);_modal=new Window{Title=title,Size=new(width,height),MinSize=new(420,220),Transient=true,Exclusive=true,Unresizable=false};AddChild(_modal);_modal.CloseRequested+=CloseModal;
        var layout=new VBoxContainer();layout.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);layout.OffsetLeft=16;layout.OffsetTop=16;layout.OffsetRight=-16;layout.OffsetBottom=-16;_modal.AddChild(layout);var heading=new HBoxContainer();layout.AddChild(heading);Text(heading,title,22);var close=Button(heading,"× Fechar",CloseModal,"Fechar janela");close.CustomMinimumSize=new(104,40);close.AutowrapMode=TextServer.AutowrapMode.Off;close.SizeFlagsHorizontal=Control.SizeFlags.Fill;
        var scroll=new ScrollContainer{HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled,SizeFlagsVertical=Control.SizeFlags.ExpandFill,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};layout.AddChild(scroll);var box=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};box.AddThemeConstantOverride("separation",8);scroll.AddChild(box);_modal.PopupCentered();FitModal(_modal,box);return box;
