    async void FitModal(Window window,VBoxContainer body)
    {
        await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);if(_modal!=window||!GodotObject.IsInstanceValid(window))return;var viewport=GetViewport().GetVisibleRect().Size;var wanted=(int)Math.Ceiling(body.GetCombinedMinimumSize().Y+100);window.Size=new(window.Size.X,Math.Clamp(wanted,220,(int)viewport.Y-72));window.PopupCentered();
    }
    void CloseModal(){if(_modal!=null){_modal.Hide();_modal.QueueFree();_modal=null;}}
    void ShowCities(){var box=Modal("Cidades");Text(box,"Nova cidade",22);var row=new HBoxContainer();box.AddChild(row);Text(row,"Código do mapa");var seed=new SpinBox{MinValue=0,MaxValue=int.MaxValue,Value=42,CustomMinimumSize=new(160,40)};row.AddChild(seed);Button(row,"+ Criar",()=>NewCity((int)seed.Value));Text(box,"Salvamento automático · minutos (0 desliga)",18);var autosave=new SpinBox{MinValue=0,MaxValue=60,Step=1,Value=_autosaveMinutes};box.AddChild(autosave);autosave.ValueChanged+=v=>_autosaveMinutes=v;Button(box,"▣ Salvar agora",SaveCity);Text(box,"Cidades salvas",22);foreach(var saved in CitySaves.List()){var copy=saved;Button(box,copy.Name+" • "+copy.At.ToString("dd/MM/yyyy HH:mm"),()=>LoadCity(copy.Id));}}
    void ShowPeople(){var box=Modal("SIMs e empresas");Text(box,"População: "+_sim.Population,22);foreach(var c in _sim.State.Citizens.Where(c=>c.Alive)){var id=c.Id;Button(box,c.Name+" • "+c.Activity+" • carteira "+Cash(_sim.Balance(c.Account)),()=>InspectCitizen(id));}Text(box,"Empresas",22);foreach(var c in _sim.State.Companies){Text(box,c.Name+" • "+Cash(_sim.Balance(c.Account))+" • "+(c.Active?"ativa":"encerrada"),18);Text(box,c.Decision);foreach(var id in c.Buildings){var b=_sim.State.Buildings.FirstOrDefault(b=>b.Id==id&&!b.Removed);if(b==null)continue;var bid=b.Id;Button(box,b.Definition.Name,()=>{ClearTool();_selectedBuilding=bid;RefreshInspection();CloseModal();});}}Text(box,"Candidatos externos",20);Text(box,"Famílias aguardando: "+_sim.State.FamilyCandidates.Count(c=>!c.Migrated)+" • empresas aguardando: "+_sim.State.CompanyCandidates.Count(c=>!c.Entered));foreach(var cause in _sim.State.FamilyCandidates.Where(c=>!c.Migrated).Select(c=>c.Cause).Distinct())Text(box,cause,14);}
    void ShowAlerts(){var box=Modal("Causas, obras e entregas");var s=_sim.State;Text(box,"Infraestrutura",22);Text(box,$"Água: {s.PotableCapacity:N1} / demanda {s.WaterDemand:N1} • captação {s.RawWaterCapacity:N1}");Text(box,$"Energia: {s.ElectricityCapacity:N1} / demanda {s.ElectricityDemand:N1} • vento {s.WindFactor:P0}");Text(box,$"Esgoto: {s.SewageCapacity:N1} / demanda {s.SewageDemand:N1} • sem tratamento {s.UntreatedSewage:N1}");Text(box,"Poluição da fonte natural: "+s.LakePollution.ToString("P1"));Text(box,"Obras",22);foreach(var p in s.Projects.Where(p=>p.Status!=WorkStatus.Completed)){var projectId=p.Id;Button(box,$"#{p.Id} {p.Progress:P0} • {p.Cause} • pago {Cash(p.CostPaid)} • compromisso {Cash(p.BudgetRemaining)}",()=>{ClearTool();_selectedBuilding=null;_selectedCitizen=null;_selectedVehicle=null;_selectedRoad=null;_selectedProject=projectId;RefreshInspection();CloseModal();});}Text(box,"Entregas em trânsito",22);foreach(var shipment in s.Shipments.Where(s=>!s.Complete)){var v=s.Vehicles.First(v=>v.Id==shipment.VehicleId);var id=v.Id;Button(box,"#"+shipment.Id+" • "+v.Cause+" • "+string.Join(", ",shipment.Cargo.Select(k=>ResourceName(k.Key)+" "+k.Value.ToString("N1"))),()=>{ClearTool();_selectedVehicle=id;RefreshInspection();CloseModal();});}Text(box,"Construções",22);foreach(var b in s.Buildings.Where(b=>!b.Removed).OrderBy(b=>b.Completed?1:0).ThenBy(b=>b.Definition.Private?1:0)){var id=b.Id;Button(box,b.Definition.Name+" • "+b.Cause,()=>{ClearTool();_selectedBuilding=id;RefreshInspection();CloseModal();});}Text(box,"História da cidade",22);foreach(var e in s.CityEvents.TakeLast(20).Reverse())Text(box,e.At.ToString("dd/MM HH:mm")+" • "+e.Description,14);}
    void ShowFinances(){var box=Modal("Finanças municipais");Text(box,"Caixa: "+Cash(_sim.CityBalance),22);Text(box,"Comprometido: "+Cash(_sim.Committed)+" • disponível: "+Cash(_sim.Available));Text(box,"Salários essenciais acumulados: "+Cash(_sim.MunicipalCriticalWagesPending)+" • preservados antes de cobrar empréstimos e outras dívidas.",14);Text(box,"Tarifas automáticas por consumo: água "+Cash(_sim.State.WaterUnitPrice)+" • energia "+Cash(_sim.State.ElectricityUnitPrice));Text(box,"Referência de custo operacional; só consumo efetivo gera conta. Capacidade ociosa não vira tarifa infinita.",14);Text(box,"Pagamentos e receitas efetivos",20);foreach(var g in _sim.State.Ledger.Where(l=>l.From=="city"||l.To=="city").GroupBy(l=>l.Category))Text(box,g.Key+" • entrada "+Cash(g.Where(l=>l.To=="city").Sum(l=>l.Amount))+" • saída "+Cash(g.Where(l=>l.From=="city").Sum(l=>l.Amount)));Text(box,"Dívidas existentes",20);foreach(var d in _sim.State.Obligations.Where(d=>d.Outstanding>0))Text(box,AccountName(d.Debtor)+" → "+AccountName(d.Creditor)+" • "+d.Kind+" • "+Cash(d.Outstanding),14);
        Text(box,"Impostos patrimoniais anuais (%)",20);Text(box,"Cobrança mensal: valor de mercado atual × alíquota anual ÷ 12.",14);var categories=new[]{"Residencial · baixa densidade","Residencial · alta densidade","Comercial · baixa densidade","Comercial · alta densidade","Industrial · baixa densidade","Industrial · alta densidade"};for(var i=0;i<6;i++){var index=i;var row=new HBoxContainer();box.AddChild(row);Text(row,categories[i]);var rate=new SpinBox{MinValue=0,MaxValue=8,Step=.1,Value=(double)_sim.State.TaxRates[i]*100,CustomMinimumSize=new(120,36)};row.AddChild(rate);rate.ValueChanged+=value=>_sim.SetTax(index,(decimal)value/100);}
        Text(box,"Empréstimo manual",20);Text(box,"Limite de principal em aberto: "+Cash(_sim.State.Tuning.LoanLimit)+" • prazo: "+_sim.State.Tuning.LoanMonths+" meses");Text(box,"Juros: "+(_sim.State.Tuning.LoanMonthlyInterest*100).ToString("N1",Pt)+"% ao mês sobre o principal restante. Atraso impede novo empréstimo.",14);foreach(var contract in _sim.State.Loans.Where(l=>l.Principal>0))Text(box,"Contrato #"+contract.Id+" • principal "+Cash(contract.Principal)+" • "+contract.RemainingMonths+" parcelas restantes • próximo vencimento "+contract.NextDue.ToString("dd/MM/yyyy"),14);var loan=new SpinBox{MinValue=.01,MaxValue=(double)_sim.State.Tuning.LoanLimit,Step=.01,Value=10000};box.AddChild(loan);var loanFeedback=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};Button(box,"Contratar empréstimo",()=>{var result=_sim.Borrow((decimal)loan.Value);loanFeedback.Text=result.Message;});box.AddChild(loanFeedback);Text(box,"Últimas transações",20);foreach(var l in _sim.State.Ledger.TakeLast(20).Reverse())Text(box,l.At.ToString("dd/MM HH:mm")+" • "+AccountName(l.From)+" → "+AccountName(l.To)+" • "+Cash(l.Amount)+" • "+l.Reason,14);}
    void ShowHelp(){var box=Modal("Controles");Text(box,"Construa e observe a cidade",24);foreach(var text in new[]{"Escolha uma imagem no catálogo, confira o modelo e o custo, e clique no terreno para encomendar. A ferramenta continua pronta para repetir.","Rua: clique no início, confira traçado e preço, e clique no fim para encomendar. Tab alterna o L. A prévia não gasta dinheiro.","R gira o prédio. Tab alterna o L. Enter também encomenda a prévia válida. Esc ou botão direito cancela a ferramenta.","W A S D ou botão central movem a câmera. Roda aproxima. Q/E giram a câmera.","Espaço pausa. Tecla 1: tempo real; tecla 2: 15x; tecla 3: 60x. F5 salva.","Clique em prédios, pessoas e caminhões para inspecionar. Os painéis mostram causas, dinheiro e entregas reais.","As obras precisam de ruas conectadas ao exterior. Casas e negócios não garantem moradores ou compradores.","A Prefeitura libera as ferramentas ao confirmar seu projeto. Água e energia dependem das instalações e trabalhadores reais."})Text(box,text,18);}
}
